// Writes src/odt-assets.js from the two XML files Org ships with ox-odt (etc/org/OrgOdtStyles.xml, OrgOdtContentTemplate.xml).
// Org is GPLv3+; the files are copied unchanged.  Usage: node tools/gen-odt-assets.mjs [dir]
import { readFileSync, writeFileSync } from 'node:fs';
const dir = process.argv[2] || '/usr/share/emacs/29.3/etc/org';
const read = (n) => readFileSync(`${dir}/${n}`, 'utf8');
const out = `// @ts-check
// Generated by tools/gen-odt-assets.mjs from Org's etc/org/OrgOdtStyles.xml and OrgOdtContentTemplate.xml (GPLv3+, copied unchanged).
// Do not edit by hand.

export const ODT_STYLES_XML = ${JSON.stringify(read('OrgOdtStyles.xml'))};

export const ODT_CONTENT_TEMPLATE = ${JSON.stringify(read('OrgOdtContentTemplate.xml'))};
`;
writeFileSync(new URL('../src/odt-assets.js', import.meta.url), out);
console.log('wrote src/odt-assets.js', out.length);
